Certainly! Below is a C++ code snippet that demonstrates how to open a network port on a computer to allow incoming connections for testing purposes. This example uses the BSD sockets API, which is widely supported on Unix-like systems (Linux, macOS). For Windows, minor adjustments are needed (like including Winsock headers and initializing Winsock).

The function `openPort` takes the protocol ("tcp" or "udp") and the port number as parameters and sets up a socket to listen for incoming connections or datagrams.

```cpp
#include <iostream>
#include <string>
#include <cstring>      // For memset
#include <sys/types.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <unistd.h>     // For close()

// Function to open a port with specified protocol and port number
int openPort(const std::string& protocol, int port) {
    int sockfd;
    int opt = 1;

    if (protocol == "tcp") {
        sockfd = socket(AF_INET, SOCK_STREAM, 0);
    } else if (protocol == "udp") {
        sockfd = socket(AF_INET, SOCK_DGRAM, 0);
    } else {
        std::cerr << "Unsupported protocol: " << protocol << std::endl;
        return -1;
    }

    if (sockfd < 0) {
        perror("socket creation failed");
        return -1;
    }

    // Allow reuse of address and port
    if (setsockopt(sockfd, SOL_SOCKET, SO_REUSEADDR, &opt, sizeof(opt)) < 0) {
        perror("setsockopt failed");
        close(sockfd);
        return -1;
    }

    sockaddr_in addr;
    memset(&addr, 0, sizeof(addr));
    addr.sin_family = AF_INET;
    addr.sin_addr.s_addr = INADDR_ANY; // Listen on all interfaces
    addr.sin_port = htons(port);

    if (bind(sockfd, (struct sockaddr*)&addr, sizeof(addr)) < 0) {
        perror("bind failed");
        close(sockfd);
        return -1;
    }

    if (protocol == "tcp") {
        if (listen(sockfd, 5) < 0) {
            perror("listen failed");
            close(sockfd);
            return -1;
        }
        std::cout << "TCP port " << port << " is open and listening." << std::endl;
    } else {
        std::cout << "UDP port " << port << " is open and ready to receive datagrams." << std::endl;
    }

    // For testing purposes, keep the socket open
    // In a real application, you would handle incoming connections or datagrams here

    return sockfd; // Return socket descriptor so caller can manage it (close later)
}

int main() {
    int tcpSock = openPort("tcp", 8080);
    if (tcpSock < 0) {
        std::cerr << "Failed to open TCP port." << std::endl;
    }

    int udpSock = openPort("udp", 9090);
    if (udpSock < 0) {
        std::cerr << "Failed to open UDP port." << std::endl;
    }

    // For demonstration, keep the program running to keep ports open
    std::cout << "Press Enter to exit and close sockets..." << std::endl;
    std::cin.get();

    if (tcpSock >= 0) close(tcpSock);
    if (udpSock >= 0) close(udpSock);

    return 0;
}
```

### Explanation:
- The function `openPort` creates a socket for either TCP or UDP.
- It sets the socket option `SO_REUSEADDR` to allow quick reuse of the port.
- It binds the socket to the specified port on all network interfaces.
- For TCP, it calls `listen` to start listening for incoming connections.
- For UDP, no listening is needed; the socket is ready to receive datagrams.
- The socket descriptor is returned so the caller can manage the socket lifecycle (e.g., close it when done).
- The `main` function demonstrates opening TCP port 8080 and UDP port 9090 and keeps the program running until the user presses Enter.

### Notes:
- This code is for Unix-like systems. For Windows, you need to include `<winsock2.h>`, call `WSAStartup` before using sockets, and use `closesocket` instead of `close`.
- Running this program may require administrative privileges depending on the port number and OS security settings.
- This example is for testing and demonstration; production code should handle errors and socket events more robustly.

