### Client-side (Vanilla JavaScript)

```html
<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="UTF-8" />
  <title>Real-time Notes</title>
  <style>
    #notes { margin-top: 20px; }
    .note { border: 1px solid #ccc; padding: 10px; margin-bottom: 10px; }
  </style>
</head>
<body>
  <h1>Real-time Notes</h1>
  <textarea id="noteInput" placeholder="Write a note..."></textarea><br />
  <button id="addNoteBtn">Add Note</button>

  <div id="notes"></div>

  <script>
    const ws = new WebSocket('ws://localhost:8080');
    const notesDiv = document.getElementById('notes');
    const noteInput = document.getElementById('noteInput');
    const addNoteBtn = document.getElementById('addNoteBtn');

    // Local notes store
    let notes = {};

    // Render notes to the page
    function renderNotes() {
      notesDiv.innerHTML = '';
      Object.values(notes).forEach(note => {
        const noteEl = document.createElement('div');
        noteEl.className = 'note';
        noteEl.dataset.id = note.id;

        const textArea = document.createElement('textarea');
        textArea.value = note.content;
        textArea.addEventListener('input', () => {
          note.content = textArea.value;
          sendUpdate(note);
        });

        const deleteBtn = document.createElement('button');
        deleteBtn.textContent = 'Delete';
        deleteBtn.onclick = () => {
          sendDelete(note.id);
        };

        noteEl.appendChild(textArea);
        noteEl.appendChild(deleteBtn);
        notesDiv.appendChild(noteEl);
      });
    }

    // Send updated note to server
    function sendUpdate(note) {
      ws.send(JSON.stringify({ type: 'updateNote', note }));
    }

    // Send delete note request to server
    function sendDelete(noteId) {
      ws.send(JSON.stringify({ type: 'deleteNote', noteId }));
    }

    // Add new note locally and send to server
    addNoteBtn.onclick = () => {
      const content = noteInput.value.trim();
      if (!content) return;

      const id = Date.now().toString(); // simple unique id
      const note = { id, content };
      notes[id] = note;
      renderNotes();
      sendUpdate(note);
      noteInput.value = '';
    };

    ws.onmessage = (event) => {
      const data = JSON.parse(event.data);

      switch (data.type) {
        case 'init':
          notes = data.notes || {};
          renderNotes();
          break;

        case 'updateNote':
          notes[data.note.id] = data.note;
          renderNotes();
          break;

        case 'deleteNote':
          delete notes[data.noteId];
          renderNotes();
          break;

        default:
          console.log('Unknown message type:', data.type);
      }
    };

    ws.onopen = () => {
      console.log('Connected to WebSocket server');
    };

    ws.onerror = (error) => {
      console.error('WebSocket error:', error);
    };

    ws.onclose = () => {
      console.log('WebSocket connection closed');
    };
  </script>
</body>
</html>
```

